const p = $input.first().json.body?.payload ?? {};
const chatId = String(p.from ?? '');
const alt = String(p._data?.key?.remoteJidAlt ?? p._data?.key?.senderPn ?? '');
const from = chatId.endsWith('@lid') ? alt : chatId;
let d = from.replace(/@.*/, '').replace(/\D/g, '').replace(/^0+/, '');
if (!d.startsWith('55') || (d.length !== 12 && d.length !== 13)) return [];
if (d.length === 12 && /[6-9]/.test(d[4])) d = d.slice(0, 4) + '9' + d.slice(4);
const sem9 = (d.length === 13 && d[4] === '9') ? d.slice(0, 4) + d.slice(5) : d;
const mime = String(p.media?.mimetype ?? '');
const tipo = p.hasMedia ? (mime.startsWith('audio/') ? 'audio' : 'outro') : (p.body ? 'text' : 'outro');
const midia = p.media?.url ? new URL(p.media.url, 'https://meu-waha.xiekee.easypanel.host') : null;
const sp = DateTime.now().setZone('America/Sao_Paulo');
return [{ json: {
  telefone: d,
  telefone_alt: sem9,
  wa_id: from,
  chat_id: chatId,
  message_id: p.id,
  tipo,
  texto: tipo === 'text' ? String(p.body) : '',
  audio_url: tipo === 'audio' && midia ? 'https://meu-waha.xiekee.easypanel.host' + midia.pathname : null,
  hoje: sp.toFormat('yyyy-MM-dd'),
  mes: sp.toFormat('yyyy-MM'),
  agora_sp: sp.toFormat("yyyy-MM-dd'T'HH:mm:ssZZ"),
  dia_semana: sp.setLocale('pt-BR').toFormat('cccc'),
} }];

const agora = new Date();
const vale = (r) => { const v = r.data_vencimento ? new Date(r.data_vencimento) > agora : null; return r.status === 'Ativo' ? (v === null || v) : r.status === 'Cancelado' ? v === true : false; };
const ativa = $input.all().map(i => i.json).some(r => r.telefone && vale(r));
return [{ json: { ativa } }];

const canon = (t) => { let d = String(t || '').replace(/\D/g, '').replace(/^0+/, ''); if (d.length === 10 || d.length === 11) d = '55' + d; if (d.length === 12 && d.startsWith('55') && /[6-9]/.test(d[4])) d = d.slice(0, 4) + '9' + d.slice(4); return d; };
const agora = new Date();
const ativos = new Set($('Assinaturas ativas').all().map(i => i.json).filter(r => (r.status === 'Ativo' && (!r.data_vencimento || new Date(r.data_vencimento) > agora)) || (r.status === 'Cancelado' && r.data_vencimento && new Date(r.data_vencimento) > agora)).map(r => canon(r.telefone)));
const nomes = {};
for (const p of $input.all()) if (p.json.telefone) nomes[canon(p.json.telefone)] = p.json.nome;
const hoje = DateTime.now().setZone('America/Sao_Paulo').startOf('day');
const brl = (n) => Number(n).toFixed(2).replace('.', ',').replace(/\B(?=(\d{3})+,)/g, '.');
const out = [];
for (const it of $('Contas a lembrar').all()) {
  const c = it.json;
  if (!c.id || !ativos.has(canon(c.telefone))) continue;
  const dias = Math.round(DateTime.fromISO(String(c.vencimento).slice(0, 10), { zone: 'America/Sao_Paulo' }).startOf('day').diff(hoje, 'days').days);
  const quando = dias === 0 ? 'hoje' : dias === 1 ? 'amanhã' : DateTime.fromISO(String(c.vencimento).slice(0, 10)).toFormat('dd/MM/yyyy');
  const nome = String(nomes[canon(c.telefone)] || '').trim().split(/\s+/)[0] || 'cliente';
  out.push({ json: { telefone: c.telefone, conta_id: c.id, Menssage: `Olá, ${nome}! Lembrete do FinalZap: ${c.descricao} de R$ ${brl(c.valor)} ${dias < 0 ? "venceu em" : "vence"} ${quando}.`, vencimento: c.vencimento, tipo_lembrete: dias < 0 ? "conta_vencida" : "vencimento_proximo" } });
}
return out;
